# Generated by the release workflow from .github/homebrew/toolbox.rb in WilliamThogersen/toolbox.
# Edit it there, not in the tap.
class Toolbox < Formula
  desc "CLI your AI can keep extending: Lua commands and a key vault"
  homepage "https://github.com/WilliamThogersen/toolbox"
  license "MIT"

  # `brew audit --strict` refuses url and sha256 directly in on_macos, so the universal
  # macOS binary is listed once per architecture.
  on_macos do
    on_arm do
      url "https://github.com/WilliamThogersen/toolbox/releases/download/v0.6.0/toolbox-macos.tar.gz"
      sha256 "a13b1e81a7c10610245cf8e1b1c223799ba059948a4f49955d6e11196cb2a394"
    end
    on_intel do
      url "https://github.com/WilliamThogersen/toolbox/releases/download/v0.6.0/toolbox-macos.tar.gz"
      sha256 "a13b1e81a7c10610245cf8e1b1c223799ba059948a4f49955d6e11196cb2a394"
    end
  end

  # Static binaries: they need no system libraries, whatever the distribution.
  on_linux do
    on_arm do
      url "https://github.com/WilliamThogersen/toolbox/releases/download/v0.6.0/toolbox-linux-arm64.tar.gz"
      sha256 "10bedd00dd64f447191f5319d8d550246cd1cca962f9c862a702bc35103f3f4e"
    end
    on_intel do
      url "https://github.com/WilliamThogersen/toolbox/releases/download/v0.6.0/toolbox-linux-x86_64.tar.gz"
      sha256 "ee434f9eaa17964fb0fb3e8d8c3a7fa365242ef62ca2bda5fb41fabca2947906"
    end
  end

  def install
    bin.install "toolbox"
    if OS.mac?
      # Keep Gatekeeper from blocking the binary if the download was quarantined. Fine if there is nothing to remove.
      quiet_system "/usr/bin/xattr", "-d", "com.apple.quarantine", bin/"toolbox"
    end
    # A symlink, not a copy: the keychain sees one signed binary, so it only asks once.
    bin.install_symlink "toolbox" => "tb"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/tb --version")
  end
end
